sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_despesa_bruta_com_pessoal": "despesa_bruta",
       "v_despesa_com_pessoal_ativo": "despesa_pessoal_ativo",
       "v_despesa_com_pessoal_inativo_e_pensionistas": "despesa_inativo_pensionistas",
       "v_despesa_com_pessoal_terceirizado": "despesa_terceirizados",
       "v_despesa_com_deducoes": "despesa_deducoes",
       "v_indenizacoes_por_demissao_ou_por_incentivo_a_demissao_voluntaria": "demissao_voluntaria",
       "v_despesas_com_indenizaces_de_decisoes_judiciais": "indenizacoes_judiciais",
       "v_despesas_de_exercicio_anteriores": "exercicios_anteriores",
       "v_interface_a_pensionistas_com_resumos_vinculados": "interface_pensionistas",
       "v_despesa_liquida_com_pedidos": "despesa_liquida",
       "v_receita_corrente_liquidos_sel_7406a_fibo_de_medidas": "rcl",
       "v_porcentagem_do_limite_maximo_de_rcl": "porcentagem_limite_maximo",
       "v_porcentagem_de_comprometimento_de_rcl": "porcentagem_comprometimento",
       "v_porcentagem_do_limite_prudencial_de_rcl": "porcentagem_limite_prudencial",
       "v_porcentagem_de_limite_de_alerta_de_rcl": "porcentagem_alerta",
       "v_ano": "ano",
       

       //obj
       "v_receita_corrente_liquida_rcl": "receita_corrente_liquida_rcl",
       "v_limite_de_alerta_executivo": "limite_de_alerta_executivo",
       "v_comprometimento_executivo": "comprometimento_executivo",
       "v_despesa_total_com_pessoal_executivo_anual": "despesa_total_com_pessoal_executivo_anual",

       "v_despesa_liquida_pessoal_executivo":"despesa_liquida_pessoal_executivo",
       "v_variacao_despesa_liquida_pessoal_consolidado":"variacao_despesa_liquida_pessoal_consolidado",
       "v_variacao_despesa_liquida_pessoal_executivo":"variacao_despesa_liquida_pessoal_executivo",
       "v_despesa_liquida_pessoal_consolidado":"despesa_liquida_pessoal_consolidado",
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

    outputs.despesa_bruta = fieldMapping['v_despesa_bruta_com_pessoal'];
    outputs.despesa_pessoal_ativo = fieldMapping['v_despesa_com_pessoal_ativo'];
    outputs.despesa_inativo_pensionistas = fieldMapping['v_despesa_com_pessoal_inativo_e_pensionistas'];
    outputs.despesa_terceirizados = fieldMapping['v_despesa_com_pessoal_terceirizado'];
    outputs.despesa_deducoes = fieldMapping['v_despesa_com_deducoes'];
    outputs.demissao_voluntaria = fieldMapping['v_indenizacoes_por_demissao_ou_por_incentivo_a_demissao_voluntaria'];
    outputs.indenizacoes_judiciais = fieldMapping['v_despesas_com_indenizaces_de_decisoes_judiciais'];
    outputs.exercicios_anteriores = fieldMapping['v_despesas_de_exercicio_anteriores'];
    outputs.interface_pensionistas = fieldMapping['v_interface_a_pensionistas_com_resumos_vinculados'];
    outputs.despesa_liquida = fieldMapping['v_despesa_liquida_com_pedidos'];
    outputs.rcl = fieldMapping['v_receita_corrente_liquidos_sel_7406a_fibo_de_medidas'];
    outputs.porcentagem_limite_maximo = fieldMapping['v_porcentagem_do_limite_maximo_de_rcl'];
    outputs.porcentagem_comprometimento = fieldMapping['v_porcentagem_de_comprometimento_de_rcl'];
    outputs.porcentagem_limite_prudencial = fieldMapping['v_porcentagem_do_limite_prudencial_de_rcl'];
    outputs.porcentagem_alerta = fieldMapping['v_porcentagem_de_limite_de_alerta_de_rcl'];
    outputs.ano = fieldMapping['v_ano'];
    


    //limite de retorno de variaveis de saida atingido.
   


    outputs.executivo_obj = {
        "receita_corrente_liquida_rcl":fieldMapping["v_receita_corrente_liquida_rcl"],
        "limite_de_alerta_executivo":fieldMapping["v_limite_de_alerta_executivo"],
        "comprometimento_executivo":fieldMapping["v_comprometimento_executivo"],
        "despesa_total_com_pessoal_executivo_anual":fieldMapping["v_despesa_total_com_pessoal_executivo_anual"],

        "despesa_liquida_pessoal_executivo":fieldMapping["v_despesa_liquida_pessoal_executivo"],
        "variacao_despesa_liquida_pessoal_consolidado":fieldMapping["v_variacao_despesa_liquida_pessoal_consolidado"],
        "variacao_despesa_liquida_pessoal_executivo":fieldMapping["v_variacao_despesa_liquida_pessoal_executivo"],
        "despesa_liquida_pessoal_consolidado":fieldMapping["v_despesa_liquida_pessoal_consolidado"],

    }




})(inputs, outputs);

